; c03_alu_arith -- ALU ADD / SUB / MUL / INC / DEC
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: the numeric codes of arith_op (D1); signed_mode; exact results (no 16-bit wrap)
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c03_alu_arith.expected.csv
.include "conf_defs.inc"
.main
    MOV CONST(0x0007, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0003, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU ADD unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 0, len=4, ptr=8
    ALU SUB unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 4, len=4, ptr=8
    ALU MUL unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 8, len=4, ptr=8
    ALU INC unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 12, len=4, ptr=8
    ALU DEC unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 16, len=4, ptr=8
    MOV CONST(0xFFFE, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0003, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU ADD signed
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 20, len=4, ptr=8
    ALU SUB signed
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 24, len=4, ptr=8
    ALU MUL signed
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 28, len=4, ptr=8
    ALU ADD unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 32, len=4, ptr=8
    MOV CONST(0x0003, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0007, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU SUB unsigned                           ; 3 - 7: the exact difference is -4, not a 16-bit wrap
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 36, len=4, ptr=8
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
